import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");

  const [candidateModalOpen, setCandidateModalOpen] = useState(false);
  const [editingCandidate, setEditingCandidate] = useState(null);
  const [candidateForm, setCandidateForm] = useState({ name: "", position: "", party: "" });

  const [userModalOpen, setUserModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userActionType, setUserActionType] = useState(""); // "approve" or "reject"

  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  // ------------------------ Backend Calls ------------------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Voting state fetch failed:", err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error("Pending users fetch failed:", err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error("Candidates fetch failed:", err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      console.error("Logs fetch failed:", err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Toggle voting failed:", err);
    }
  };

  const openUserModal = (user, type) => {
    setSelectedUser(user);
    setUserActionType(type);
    setUserModalOpen(true);
  };

  const closeUserModal = () => {
    setSelectedUser(null);
    setUserActionType("");
    setUserModalOpen(false);
  };

  const confirmUserAction = async () => {
    if (!selectedUser || !userActionType) return;

    try {
      const endpoint =
        userActionType === "approve"
          ? `/admin/approve-user/${selectedUser.id}`
          : `/admin/reject-user/${selectedUser.id}`;

      await api.post(endpoint);
      fetchPendingUsers();
      alert(`User ${selectedUser.name} successfully ${userActionType}d`);
      closeUserModal();
    } catch (err) {
      console.error(`${userActionType} user failed:`, err);
      if (err.response) {
        if (err.response.status === 400) alert(err.response.data.error || `Cannot ${userActionType} this user`);
        else if (err.response.status === 401) {
          alert("Unauthorized. Please login again.");
          logout();
          navigate("/login");
        } else alert(`Failed to ${userActionType} user. Check console for details.`);
      } else {
        alert(`Network/server error. Could not ${userActionType} user.`);
      }
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      console.error("Generate report failed:", err);
    }
  };

  // ------------------------ Candidate CRUD ------------------------
  const openCandidateModal = (candidate = null) => {
    setEditingCandidate(candidate);
    if (candidate) setCandidateForm({ name: candidate.name, position: candidate.position, party: candidate.party || "" });
    else setCandidateForm({ name: "", position: "", party: "" });
    setCandidateModalOpen(true);
  };

  const closeCandidateModal = () => {
    setCandidateModalOpen(false);
    setEditingCandidate(null);
  };

  const handleCandidateFormChange = (e) => {
    setCandidateForm({ ...candidateForm, [e.target.name]: e.target.value });
  };

  const saveCandidate = async () => {
    const { name, position, party } = candidateForm;
    if (!name || !position) return alert("Name and Position are required");
    try {
      if (editingCandidate) await api.put(`/admin/candidates/${editingCandidate.id}`, { name, position, party });
      else await api.post(`/admin/candidates`, { name, position, party });
      fetchCandidates();
      closeCandidateModal();
    } catch (err) {
      console.error("Save candidate failed:", err);
      alert("Failed to save candidate");
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      console.error("Delete candidate failed:", err);
      alert("Failed to delete candidate");
    }
  };

  // ------------------------ JSX ------------------------
  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold">iVote Admin Dashboard</h1>
        <button onClick={() => { logout(); navigate("/login"); }} className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700">
          Logout
        </button>
      </header>

      <main className="p-6 space-y-6">
        {/* Voting Status */}
        <section className="bg-white p-6 rounded-xl shadow-md flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold">Voting Status</h2>
            <p className={votingOpen ? "text-green-600" : "text-red-600"}>
              {votingOpen ? "Open" : "Closed"}
            </p>
          </div>
          <button
            onClick={toggleVoting}
            className={`px-6 py-3 rounded-lg font-semibold text-white ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </section>

        {/* Pending Users */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">Pending Voter Registrations</h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <table className="w-full table-auto border-collapse border border-gray-200">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border px-4 py-2">Student Number</th>
                  <th className="border px-4 py-2">Name</th>
                  <th className="border px-4 py-2">Email</th>
                  <th className="border px-4 py-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.map((user) => (
                  <tr key={user.id}>
                    <td className="border px-4 py-2">{user.studentNumber}</td>
                    <td className="border px-4 py-2">{user.name}</td>
                    <td className="border px-4 py-2">{user.email}</td>
                    <td className="border px-4 py-2 space-x-2">
                      <button
                        onClick={() => openUserModal(user, "approve")}
                        className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                      >
                        Approve
                      </button>
                      <button
                        onClick={() => openUserModal(user, "reject")}
                        className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700"
                      >
                        Reject
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        {/* Candidates, Logs, Reports */}
        {/* Keep your existing JSX for candidates, logs, reports */}
      </main>

      {/* Candidate Modal */}
      {candidateModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50">
          <div className="bg-white p-6 rounded-xl w-96">
            <h3 className="text-lg font-semibold mb-4">{editingCandidate ? "Edit Candidate" : "Add Candidate"}</h3>
            <div className="space-y-3">
              <input type="text" name="name" placeholder="Name" value={candidateForm.name} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
              <input type="text" name="position" placeholder="Position" value={candidateForm.position} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
              <input type="text" name="party" placeholder="Party (optional)" value={candidateForm.party} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
            </div>
            <div className="flex justify-end mt-4 space-x-2">
              <button onClick={closeCandidateModal} className="px-4 py-2 rounded bg-gray-300 hover:bg-gray-400">Cancel</button>
              <button onClick={saveCandidate} className="px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700">{editingCandidate ? "Save Changes" : "Add Candidate"}</button>
            </div>
          </div>
        </div>
      )}

      {/* User Approve/Reject Confirmation Modal */}
      {userModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50">
          <div className="bg-white p-6 rounded-xl w-96">
            <h3 className="text-lg font-semibold mb-4">
              {userActionType === "approve" ? "Approve User" : "Reject User"}
            </h3>
            <p>Are you sure you want to {userActionType} user <strong>{selectedUser?.name}</strong>?</p>
            <div className="flex justify-end mt-4 space-x-2">
              <button onClick={closeUserModal} className="px-4 py-2 rounded bg-gray-300 hover:bg-gray-400">Cancel</button>
              <button onClick={confirmUserAction} className={`px-4 py-2 rounded text-white ${userActionType === "approve" ? "bg-green-600 hover:bg-green-700" : "bg-red-600 hover:bg-red-700"}`}>
                {userActionType === "approve" ? "Approve" : "Reject"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
